#!/usr/bin/env bash
# Question 6: Name resolution broken. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q6_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q6_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q6_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q6_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: web
  namespace: ${Q6_NS}
spec:
  selector: { app: web }
  ports: [{ port: 80 }]
EOF
kubectl -n "${Q6_NS}" delete pod client --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q6_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"client"},"spec":{"containers":[{"name":"shell","image":"busybox:1.36","command":["sleep","infinity"]}]}}'
if ! kubectl -n "${Q6_NS}" wait --for=condition=Ready pod/client --timeout=180s; then
  kubectl -n "${Q6_NS}" describe pod/client >&2 || true
  exit 1
fi
kubectl -n "${Q6_NS}" rollout status deployment/web --timeout=180s

case "${Q6_FAULT}" in
  coredns-config-volume)
    kubectl -n kube-system get deployment coredns -o jsonpath='{.spec.strategy}' > "/var/tmp/cka-q6.strategy"
    kubectl -n kube-system patch deployment coredns --type=merge -p '{"spec":{"strategy":{"type":"RollingUpdate","rollingUpdate":{"maxUnavailable":"100%","maxSurge":0}}}}' >/dev/null
    kubectl -n kube-system patch deployment coredns --type=json -p '[{"op":"replace","path":"/spec/template/spec/volumes/0/configMap/name","value":"coredns-custom"}]' >/dev/null
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pods -l k8s-app=kube-dns -o jsonpath='{range .items[*]}{.status.containerStatuses[0].ready}{"\n"}{end}' | grep -c true)" == 0 ]] && break
      sleep 2
    done
    ;;
  coredns-hosts-plugin)
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' > /tmp/cka-Corefile
    python3 -c 'from pathlib import Path; t=Path("/tmp/cka-Corefile").read_text(); n="kubernetes cluster.local"; i="hosts {\n        127.0.0.1 web\n        fallthrough\n    }\n    "; Path("/tmp/cka-Corefile").write_text(t.replace(n, i+n, 1) if "hosts {" not in t else t)'
    grep -q '127.0.0.1 web' /tmp/cka-Corefile || { echo "could not inject hosts plugin" >&2; exit 1; }
    kubectl -n kube-system create configmap coredns --from-file=Corefile=/tmp/cka-Corefile -o yaml --dry-run=client | kubectl -n kube-system apply -f - >/dev/null
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

# The question only makes sense if the client really cannot resolve the name.
for _ in $(seq 1 60); do
  kubectl -n "${Q6_NS}" exec client -- wget -qO- -T 3 http://web 2>/dev/null | grep -q nginx || exit 0
  sleep 3
done
echo "the client still resolves web" >&2
exit 1
